def prefix_to_postfix(expression: str) -> str:
    stack = []
    for ch in reversed(expression):
        if ch.isalnum():
            stack.append(ch)
        else:
            a = stack.pop()
            b = stack.pop()
            stack.append(a + b + ch)
    return stack[0]

