#include <bits/stdc++.h>
using namespace std;

string preToPost(string pre_exp) {
    stack<string> st;
    for (int i = (int)pre_exp.size() - 1; i >= 0; --i) {
        char ch = pre_exp[i];
        if (isalnum((unsigned char)ch)) st.push(string(1, ch));
        else {
            string a = st.top(); st.pop();
            string b = st.top(); st.pop();
            st.push(a + b + ch);
        }
    }
    return st.top();
}

